import { useEffect, useState } from "react";
import { Box, Container, Stack, Typography } from "@mui/material";
import api, { mediaUrl } from "../services/api";
import type { HomeExplore, SingleResponse } from "../types/home";

export default function ExploreDevices() {
  const [data, setData] = useState<HomeExplore | null>(null);

  useEffect(() => {
    api
      .get<SingleResponse<HomeExplore>>("/home-explore", { params: { populate: "image" } })
      .then((payload) => setData(payload.data || null))
      .catch(() => setData(null));
  }, []);

  if (!data) return null;

  return (
    <Box sx={{ py: { xs: 6, md: 8 } }}>
      <Container maxWidth="lg">
        <Stack direction={{ xs: "column", md: "row" }} alignItems="center" spacing={4}>
          <Box sx={{ flex: 1 }}>
            <Typography sx={{ color: "#17224d", fontSize: { xs: 24, md: 32 }, fontWeight: 600, mb: 2 }}>
              {data.title}
            </Typography>
            <Typography sx={{ color: "#5a6473", fontSize: 16 }}>{data.description}</Typography>
          </Box>
          {mediaUrl(data.image) ? (
            <Box sx={{ flex: 1 }}>
              <Box
                component="img"
                src={mediaUrl(data.image)}
                alt={data.image?.alternativeText || data.title || "Explore"}
                sx={{ width: "100%" }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
    </Box>
  );
}
